var pending: DispatchWorkItem?
func onText(_ q: String) {
    pending?.cancel()
    let work = DispatchWorkItem { search(q) }
    pending = work
    DispatchQueue.main.asyncAfter(deadline: .now() + 0.3, execute: work)
}

